<script setup>
import { reactive,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { useAuthStore } from '../stores/auth'
const form=reactive({account:'alice',password:'demo123'}),loading=ref(false),auth=useAuthStore(),router=useRouter(),route=useRoute();async function submit(){loading.value=true;try{await auth.login(form);ElMessage.success('欢迎回来');router.replace(route.query.redirect|| (auth.isAdmin?'/admin':'/tasks'))}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
</script>
<template><div class="auth-page"><section class="auth-visual"><div class="brand-mark">C</div><h1>互助，<br/>让校园更近。</h1><p>发布一个小任务，交换一项新技能。每一次可靠履约，都在为你的校园信用加分。</p></section><section class="auth-form-wrap"><div class="auth-form surface"><h2>登录 CampusLink</h2><p>使用校园账号进入互助社区</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="用户名或校园邮箱"><el-input v-model="form.account" size="large" placeholder="请输入账号"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password size="large" @keyup.enter="submit"/></el-form-item><el-button class="full" size="large" type="primary" :loading="loading" @click="submit">登录</el-button></el-form><p style="text-align:center;margin:22px 0 0">还没有账号？ <router-link to="/register" style="color:#315f55;font-weight:700">立即注册</router-link></p><el-alert style="margin-top:18px" :closable="false" title="演示账号 alice / demo123；管理员 admin / admin123" type="success"/></div></section></div></template>
